-- Módulo 73: maestro plano de sucursales; sin asignaciones de otros módulos.
CREATE TABLE "Sucursales" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Codigo" varchar(20) NOT NULL CHECK ("Codigo" = btrim("Codigo") AND length("Codigo") > 0),
    "Nombre" varchar(150) NOT NULL CHECK ("Nombre" = btrim("Nombre") AND length("Nombre") > 0),
    "Tipo" varchar(10) NOT NULL CHECK ("Tipo" IN ('Filial','Planta','Oficina')),
    "Pais" varchar(100) NOT NULL CHECK ("Pais" = btrim("Pais") AND length("Pais") > 0),
    "Ciudad" varchar(100) NOT NULL CHECK ("Ciudad" = btrim("Ciudad") AND length("Ciudad") > 0),
    "Direccion" varchar(300) NOT NULL CHECK ("Direccion" = btrim("Direccion") AND length("Direccion") > 0),
    "Contacto" varchar(100),
    "Email" varchar(150),
    "Telefono" varchar(30),
    "Observaciones" varchar(500),
    "FechaApertura" timestamptz,
    "FechaRegistro" timestamptz NOT NULL,
    "Activa" boolean NOT NULL DEFAULT true,
    "FechaCambioEstado" timestamptz
);
CREATE UNIQUE INDEX "IX_Sucursales_Codigo" ON "Sucursales" (lower(btrim("Codigo")));
